mod solution;

fn main() {
    let cases = [
    (r#"[2,1,2,4,3]"#, r#"4,2,4,-1,-1"#),
    (r#"[1,3,2]"#, r#"3,-1,-1"#),
    (r#"
[1,3,2]
"#, r#"3,-1,-1"#),
    (r#"  
[2,1,2,4,3]
  "#, r#"4,2,4,-1,-1"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS next-greater-stack");
}
